<script lang="ts">
  import {searchableSelect} from '#lib/client/searchable-select.ts';
 import {refreshAll} from '$app/navigation';
 import {command,display,permitted,request} from '#lib/client/api.ts';
 import type {AppData,Row} from '#lib/client/types.ts';
 import Icon from './Icon.svelte';
 import Status from './Status.svelte';
 import ReferencePicker from './ReferencePicker.svelte';
 let {data}:{data:AppData}=$props();
 const uid=$props.id();
 let recipient=$state(''),subject=$state(''),body=$state(''),attachments:string[]=$state([]),draft:Row|null=$state(null),preview=$state(false),confirmed=$state(false);
 let busy=$state(false),error=$state(''),notice=$state(''),resolve:Row|null=$state(null),outcome=$state(''),evidence=$state(''),providerReference=$state(''),reason=$state(''),acceptedAt=$state(''),password=$state(''),resolvedConfirmed=$state(false),resolutionKey=$state('');
 let redraft:Row|null=$state(null),redraftConfirmed=$state(false);
 const history=$derived(data.related?.outgoing_messages||[]);
 const mailReady=$derived(!!data.integrations?.mail?.available);
 const attachmentChoices=$derived.by(()=>{const choices:Row[]=(data.related?.mail_attachments||[]).map(file=>({...file,version_id:file.current_version_id}));for(const file of draft?.attachment_snapshot||[])if(!choices.some(choice=>choice.version_id===file.documentVersionId))choices.push({name:file.name,version_id:file.documentVersionId,revision:null});return choices;});
 const scope=$derived({order_id:data.module?.slug==='orders'?data.detail?.id:undefined,customer_id:data.module?.slug==='customers'?data.detail?.id:data.module?.slug==='orders'?data.detail?.customer_id:undefined,supplier_id:data.module?.slug==='suppliers'?data.detail?.id:undefined});
 function edit(email:Row){draft=email;recipient=email.recipient;subject=email.subject;body=email.body;attachments=[...(email.attachment_version_ids||[])];confirmed=false;preview=false;error='';notice='';}
 function newDraft(){draft=null;recipient='';subject='';body='';attachments=[];preview=false;confirmed=false;error='';notice='';}
 async function run(action:()=>Promise<void>){if(busy)return;busy=true;error='';notice='';try{await action();await refreshAll().catch(()=>{});}catch(cause){error=cause instanceof Error?cause.message:'Der Schritt konnte nicht bestätigt werden. Ihre Eingaben bleiben erhalten.';}finally{busy=false;}}
 async function save(event:SubmitEvent){event.preventDefault();await run(async()=>{const payload={...scope,recipient,subject,body,attachment_version_ids:attachments};draft=await command(draft?'communication.email.update':'communication.email.create',draft?.id,payload,draft?.version);confirmed=false;preview=true;notice='Der Entwurf ist gespeichert. Prüfen Sie jetzt Absender, Empfänger, Nachricht und jede genaue Anlagenfassung.';});}
 async function send(){if(!draft||!confirmed||!mailReady)return;await run(async()=>{await command('communication.email.send',draft!.id,{confirm_hash:draft!.content_hash},draft!.version);newDraft();notice='Der Versandauftrag ist eingereiht. Erst ein Annahmenachweis bestätigt die Übergabe an den Mailanbieter. Aktualisieren Sie den Stand bei Bedarf unten.';});}
 function openResolution(email:Row){resolve=email;outcome='';evidence='';providerReference='';reason='';acceptedAt='';password='';resolvedConfirmed=false;resolutionKey=crypto.randomUUID();error='';notice='';}
 async function resolveMail(event:SubmitEvent){event.preventDefault();if(!resolve||!resolvedConfirmed)return;await run(async()=>{if(!['accepted','not_accepted'].includes(outcome))throw new Error('Wählen Sie das tatsächlich belegte Ergebnis.');await request('/api/v1/reauth',{password});await command('communication.email.resolve',resolve!.id,{outcome,evidence_document_version_id:evidence,provider_reference:providerReference,reason,...(outcome==='accepted'?{accepted_at:new Date(acceptedAt).toISOString()}:{}),confirmed:true},resolve!.version,resolutionKey);resolve=null;password='';notice=outcome==='accepted'?'Die nachgewiesene Übergabe ist unveränderlich dokumentiert. Eine Zustellung im Postfach wird damit nicht behauptet.':'Die nachgewiesene Nichtübergabe ist dokumentiert. Für einen erneuten Versand müssen Sie bewusst einen neuen Entwurf erstellen und prüfen.';});}
 async function createRedraft(){if(!redraft||!redraftConfirmed)return;await run(async()=>{const created=await command('communication.email.redraft',redraft!.id,{confirmed:true},redraft!.version);redraft=null;redraftConfirmed=false;edit(created);notice='Ein neuer, verknüpfter Entwurf wurde erstellt. Prüfen und speichern Sie ihn vor einer eigenen Versandfreigabe.';});}
 function statusHelp(email:Row){if(email.status==='provider_accepted')return'Übergabe an den Mailanbieter nachgewiesen; keine Bestätigung des Eingangs im Postfach.';if(email.status==='outcome_unknown')return'Eine Übermittlung ist möglich. Keine erneute Sendung, bevor der konkrete Ausgang geklärt wurde.';if(email.status==='sending')return'Der Mailanbieter wird gerade angesprochen. Warten Sie ab und aktualisieren Sie den Stand.';if(email.status==='not_accepted')return'Die Nichtübergabe wurde anhand eines konkreten Nachweises ausdrücklich belegt. Die alte Nachricht bleibt unverändert.';if(email.status==='queued')return'Zur Verarbeitung eingereiht; noch kein Nachweis einer Übergabe.';if(email.status==='failed')return'Dieser Versuch ist beendet. Prüfen Sie den Fehler vor einem bewusst neu erstellten Entwurf.';return'Gespeicherter Entwurf; noch keine Versandfreigabe.';}
</script>

{#if error}<div class="notice error mb" role="alert">{error}</div>{/if}
{#if notice}<div class="notice info mb" role="status">{notice}</div>{/if}
{#if !mailReady}<div class="notice warning mb"><div><strong>E-Mail-Versand noch einzurichten</strong><p>Sie können Entwürfe mit geprüften Anlagen vorbereiten. Der Versand bleibt bis zur Einrichtung eines SMTP-Absenders gesperrt.{#if permitted(data,'admin.integrations')} <a class="text-link" href="/settings">SMTP in den Einstellungen einrichten</a>{:else} Wenden Sie sich dafür an Ihren Superadmin.{/if}</p></div></div>{/if}

{#if preview&&draft}
 <div class="mail-preview">
  <div class="mail-preview-heading"><h3>Verbindliche Versandvorschau</h3><span class="small">Entwurf · Version {draft.version}</span></div>
  <dl><dt>Absender</dt><dd>{draft.sender}</dd>{#if draft.reply_to}<dt>Antwort an</dt><dd>{draft.reply_to}</dd>{/if}<dt>Empfänger</dt><dd>{draft.recipient}</dd><dt>Betreff</dt><dd>{draft.subject}</dd></dl>
  <p class="mail-body">{draft.body}</p>
  <h4>Genau diese Anlagen</h4>{#if draft.attachment_snapshot?.length}<ul class="mail-attachments">{#each draft.attachment_snapshot as file}<li>{file.name}<span class="field-help">Fest gebundene Originalversion · SHA-256 {file.sha256?.slice(0,12)}…</span></li>{/each}</ul>{:else}<p class="field-help">Keine Anlagen ausgewählt.</p>{/if}
 </div>
 <label class="check-field mt"><input type="checkbox" bind:checked={confirmed}/><span>Ich habe Absender, Empfänger, Nachricht und jede oben genannte Originalversion geprüft und möchte genau diesen Stand versenden.</span></label>
 <div class="inline-actions mt"><button class="btn" type="button" disabled={busy} onclick={()=>{preview=false;confirmed=false;}}>Entwurf bearbeiten</button><button class="btn primary" type="button" disabled={busy||!confirmed||!mailReady||!draft.content_hash} onclick={send}>Jetzt ausdrücklich senden<Icon name="mail" size={16}/></button></div>
{:else}
 <form onsubmit={save}>
  <div class="mail-preview-heading mb"><h3>{draft?'Gespeicherten Entwurf bearbeiten':'E-Mail vorbereiten'}</h3>{#if draft}<button class="text-link" type="button" disabled={busy} onclick={newDraft}>Neuen Entwurf beginnen</button>{/if}</div>
  <div class="field-grid"><div class="field full"><label for={`${uid}-recipient`}>Empfänger *</label><input id={`${uid}-recipient`} type="email" bind:value={recipient} required maxlength="320" autocomplete="off"/><span class="field-help">Die Adresse des tatsächlichen Empfängers. Vor dem Senden wird sie nochmals angezeigt.</span></div><div class="field full"><label for={`${uid}-subject`}>Betreff *</label><input id={`${uid}-subject`} bind:value={subject} required maxlength="300" placeholder="Zum Beispiel: Ihr bestätigter Lieferumfang"/></div><div class="field full"><label for={`${uid}-body`}>Nachricht *</label><textarea id={`${uid}-body`} bind:value={body} required maxlength="100000" rows="6"></textarea></div></div>
  <fieldset class="mail-files mt"><legend>Freigegebene Anlagen dieser Akte</legend><p class="field-help">Wählen Sie jede genaue Originalfassung bewusst aus. Versandanlagen sind auf 10 MB je Datei begrenzt; größere Originale können Sie im freigegebenen privaten Dokumentzugang bereitstellen. Interne Kalkulationen und Personalunterlagen sind ausgeschlossen. Rechnungen werden erst nach Originalprüfung und Archivierung angeboten.</p>{#each attachmentChoices as file}<label class="check-field mt"><input type="checkbox" value={file.version_id} bind:group={attachments}/><span>{file.name}<span class="field-help">{file.revision?`Originalversion ${file.revision}`:'Bereits im Entwurf gebundene Originalversion'}{#if file.download_url} · <a class="text-link" href={file.download_url} data-sveltekit-reload download target="_blank" rel="noreferrer">Original ansehen</a>{/if}</span></span></label>{/each}{#if !attachmentChoices.length}<p class="field-help mt">Aktuell ist keine geprüfte externe Fassung dieser Akte verfügbar. Sie können die Nachricht ohne Anlage vorbereiten.</p>{/if}</fieldset>
  <button class="btn primary mt" disabled={busy}>{busy?'Wird gespeichert …':'Entwurf speichern & Vorschau prüfen'}<Icon name="arrow" size={16}/></button><p class="field-help mt">Dieser Schritt speichert nur den Entwurf. Eine E-Mail wird erst nach der eigenen Versandbestätigung im nächsten Schritt eingereiht.</p>
 </form>
{/if}

<section class="mail-history mt">
 <div class="mail-preview-heading"><div><h3>Ausgang dieser Akte</h3><p class="field-help">Die letzten 50 Entwürfe und Versandstände. Aktualisierung auf Ihren Wunsch.</p></div><button class="btn small" type="button" disabled={busy} onclick={()=>run(async()=>{notice='Der aktuelle Versandstand wurde geladen.';})}><Icon name="refresh" size={15}/>Stand aktualisieren</button></div>
 {#if !history.length}<p class="field-help mt">Noch kein Versandentwurf zu dieser Akte gespeichert.</p>{/if}
 {#each history as email(email.id)}
  <article class="mail-history-item">
   <div class="mail-preview-heading"><div><h4>{email.subject}</h4><p class="small muted">An {email.recipient} · {display(email.created_at,'created_at')}</p></div><Status value={email.status}/></div>
   <p class="field-help mt">{statusHelp(email)}</p>{#if email.last_error}<p class="field-error mt">{email.last_error}</p>{/if}
   <details class="mt"><summary class="text-link">Nachricht, Anlagen und Nachweis ansehen</summary><dl class="mt"><dt>Absender</dt><dd>{email.sender}</dd>{#if email.reply_to}<dt>Antwort an</dt><dd>{email.reply_to}</dd>{/if}<dt>Empfänger</dt><dd>{email.recipient}</dd>{#if email.accepted_at||email.sent_at}<dt>Nachgewiesene Übergabe</dt><dd>{display(email.accepted_at||email.sent_at,'created_at')}</dd>{/if}{#if email.provider_reference}<dt>Anbieterreferenz</dt><dd>{email.provider_reference}</dd>{/if}{#if email.evidence_source}<dt>Nachweis</dt><dd>{email.evidence_source==='smtp'?'Ausdrückliche SMTP-Annahme':'Dokumentierte manuelle Prüfung'}</dd>{/if}</dl><p class="mail-body">{email.body}</p>{#each email.attachments||[] as file}<p class="small mt"><a class="text-link" href={file.download_url} data-sveltekit-reload download target="_blank" rel="noreferrer">{file.name} · Originalversion {file.revision}</a></p>{/each}{#if email.evidence_document_id}<p class="small mt"><a class="text-link" href={`/api/v1/documents/${email.evidence_document_id}/download?version=${email.evidence_document_version_id}`} data-sveltekit-reload download target="_blank" rel="noreferrer">Versandnachweis: {email.evidence_name||'genaue Originalversion'}</a></p>{/if}{#if email.evidence_reason}<p class="field-help mt">{email.evidence_reason}</p>{/if}<p class="field-help mt">Nachrichtenkennung: {email.message_id}</p></details>
   {#if email.status==='draft'}<button class="btn small mt" type="button" disabled={busy} onclick={()=>edit(email)}>Entwurf öffnen</button>{:else if email.status==='outcome_unknown'}<button class="btn small mt" type="button" disabled={busy} onclick={()=>openResolution(email)}>Ausgang anhand eines Nachweises klären</button>{:else if ['failed','not_accepted'].includes(email.status)}<button class="btn small mt" type="button" disabled={busy} onclick={()=>{redraft=email;redraftConfirmed=false;}}>Bewusst neuen Entwurf erstellen</button>{/if}
  </article>
 {/each}
</section>

{#if resolve}<section class="mail-review mt" aria-labelledby={`${uid}-resolve-title`}><h3 id={`${uid}-resolve-title`}>Ungeklärten Versand dokumentieren</h3><p class="field-help mt">„{resolve.subject}“ an {resolve.recipient}. Prüfen Sie zuerst den tatsächlichen Anbieter- oder Empfängernachweis. Eine Vermutung genügt nicht. Die alte Nachricht wird nicht erneut versendet.</p><form class="mt" onsubmit={resolveMail}><div class="field-grid"><div class="field full"><label for={`${uid}-outcome`}>Was ist konkret belegt? *</label><select use:searchableSelect={outcome} id={`${uid}-outcome`} bind:value={outcome} required><option value="">Nachgewiesenes Ergebnis auswählen</option><option value="accepted">Übergabe an den Mailanbieter nachgewiesen</option><option value="not_accepted">Nichtübergabe an den Mailanbieter ausdrücklich belegt</option></select></div><div class="field full"><label for={`${uid}-proof`}>Genaue Originalversion des Nachweises *</label><ReferencePicker id={`${uid}-proof`} reference="document-versions" bind:value={evidence} required/><span class="field-help">Zum Beispiel ein geprüftes Versandprotokoll oder eine konkrete schriftliche Anbieterbestätigung. Den Nachweis bei Bedarf zuerst unter Dokumente aufnehmen.</span></div><div class="field full"><label for={`${uid}-reference`}>Referenz im Nachweis *</label><input id={`${uid}-reference`} bind:value={providerReference} required minlength="3" maxlength="1000"/><span class="field-help">Die konkrete Vorgangs- oder Nachrichtenreferenz aus dem Nachweis.</span></div>{#if outcome==='accepted'}<div class="field full"><label for={`${uid}-accepted`}>Tatsächliche Übergabe laut Nachweis *</label><input id={`${uid}-accepted`} type="datetime-local" bind:value={acceptedAt} required/><span class="field-help">Der belegte Zeitpunkt, nicht der Zeitpunkt Ihrer jetzigen Prüfung.</span></div>{/if}<div class="field full"><label for={`${uid}-reason`}>Prüfergebnis und Begründung *</label><textarea id={`${uid}-reason`} bind:value={reason} required minlength="20" maxlength="5000" rows="4"></textarea></div><div class="field full"><label for={`${uid}-password`}>Eigenes Passwort zur Bestätigung *</label><input id={`${uid}-password`} type="password" autocomplete="current-password" bind:value={password} required/></div></div><label class="check-field mt"><input type="checkbox" bind:checked={resolvedConfirmed} required/><span>Ich habe den konkreten Nachweis diesem unveränderten Nachrichtenstand zugeordnet und bestätige das oben belegte Ergebnis.</span></label><div class="inline-actions mt"><button class="btn" type="button" disabled={busy} onclick={()=>{resolve=null;password='';}}>Abbrechen</button><button class="btn primary" disabled={busy||!resolvedConfirmed}>Ergebnis unveränderlich dokumentieren</button></div></form></section>{/if}
{#if redraft}<section class="mail-review mt"><h3>Neuen Versand getrennt vorbereiten</h3><p class="field-help mt">Die alte Nachricht „{redraft.subject}“ bleibt unverändert. Es entsteht ein neuer Entwurf mit neuer Nachrichtenkennung. Die aktuelle Absenderverbindung und alle Anlagen werden erneut geprüft.</p><label class="check-field mt"><input type="checkbox" bind:checked={redraftConfirmed}/><span>Ich möchte bewusst einen neuen Entwurf erstellen und anschließend erneut prüfen. Hierdurch wird noch keine E-Mail versendet.</span></label><div class="inline-actions mt"><button class="btn" type="button" disabled={busy} onclick={()=>redraft=null}>Abbrechen</button><button class="btn primary" type="button" disabled={busy||!redraftConfirmed} onclick={createRedraft}>Neuen Entwurf erstellen</button></div></section>{/if}

<style>
 .mail-preview,.mail-review{padding:24px;border:1px solid var(--line);border-radius:8px;background:var(--wash);min-width:0}.mail-preview-heading{display:flex;justify-content:space-between;gap:18px;align-items:start}.mail-preview-heading>div{min-width:0}.mail-preview-heading h3,.mail-preview-heading h4{overflow-wrap:anywhere}.mail-body{white-space:pre-wrap;overflow-wrap:anywhere;padding:20px 0;color:var(--ink);line-height:1.6}.mail-attachments{padding-left:20px}.mail-attachments li+li{margin-top:12px}.mail-attachments .field-help{display:block;margin-top:5px}.mail-files{margin-left:0;margin-right:0;padding:20px 0;border:0;border-top:1px solid var(--line);min-width:0}.mail-files legend{padding-right:12px;font-size:14px;font-weight:500}.mail-history{border-top:1px solid var(--line);padding-top:28px}.mail-history-item{padding:24px 0;border-bottom:1px solid var(--line)}.mail-history-item:last-child{border-bottom:0;padding-bottom:0}.mail-history-item dd,.mail-preview dd{overflow-wrap:anywhere}.mail-review{margin-top:28px}details>summary{cursor:pointer;min-height:28px}.small.muted{color:var(--muted);margin-top:7px}@media(max-width:760px){.mail-preview,.mail-review{padding:18px}.mail-preview-heading{flex-wrap:wrap}.mail-preview-heading .btn{min-height:48px}.mail-preview-heading h3,.mail-preview-heading h4{font-size:15px}.mail-history-item{padding:22px 0}details>summary{min-height:44px;display:flex;align-items:center}.mail-preview dd{min-width:0}.mail-files .field-help{font-size:12px}}
</style>
